package com.ynxweb4.shop;
import static org.junit.Assert.*;
import org.junit.Test;import org.json.*;import java.time.Instant;import java.util.*;import java.io.IOException;import java.util.concurrent.atomic.AtomicInteger;
public final class BuyerJourneyTest {
 static final String A=NativeProductStateTest.A,B=NativeProductStateTest.B;
 static class Memory implements NativeCart.Storage,PayHandoffRecovery.Storage,OfflineMutationQueue.Storage {final Map<String,String> data=new HashMap<>();boolean fail;public String get(String key){return data.getOrDefault(key,"");}public void put(String key,String value)throws Exception{if(fail)throw new IOException("original Store failure");data.put(key,value);}public void putAll(Map<String,String> updates)throws Exception{if(fail)throw new IOException("original Store failure");data.putAll(updates);}}
 static ProductSession session(String binding)throws Exception{NativeProductState state=NativeProductStateTest.create(new NativeProductStateTest.Memory());JSONObject ctx=state.context(),target=NativeProductStateTest.target(ctx,binding);target.put("version","2").put("expiresAt",Instant.now().plusSeconds(300).toString());return ProductSession.nativeSession(target,ctx,Instant.now());}
 static JSONObject order()throws Exception{return new JSONObject().put("ID","ord_original").put("Buyer","0x"+"1".repeat(40)).put("WalletBuyer",A).put("StoreID","store_original").put("TotalYNXT",8).put("Currency","YNXT").put("Status","payment_pending");}
 static JSONObject invoice()throws Exception{return new JSONObject().put("order",order().put("InvoiceID","inv_original").put("PayIntentID","intent_original")).put("invoiceId","inv_original").put("intentId","intent_original").put("deepLink","ynxpay://invoice/inv_original");}
 static void cart(Memory m)throws Exception{JSONArray items=new JSONArray().put(new JSONObject().put("ProductID","p").put("VariantID","v").put("Quantity",1));m.put("cart:"+A,items.toString());m.put(NativeCart.key(A),new JSONObject().put("account",A).put("ready",true).put("dirty",false).put("stamp","original-stamp").put("revision","original-cart-revision").put("base",items).put("history",new JSONArray()).toString());}
 @Test public void canonicalCheckoutPreservesRetiredSessionAndUnknownOriginalKeyAcrossColdReopen()throws Exception{Memory m=new Memory();m.put("commerce_session","original-retired-record");cart(m);ProductSession session=session("a".repeat(64));JSONObject address=new JSONObject().put("Line1","original address");CheckoutIntent.Prepared first=CheckoutIntent.prepareSyncedCart(m,session,address,id->"store_original");assertEquals("original-retired-record",m.get("commerce_session"));assertEquals("original-cart-revision",first.body.getString("CartRevision"));CheckoutIntent.markDispatched(m,session,first.body);String saved=m.get("checkout:"+A);assertThrows(CheckoutIntent.UnresolvedException.class,()->CheckoutIntent.prepareSyncedCart(m,session("b".repeat(64)),address,id->"store_original"));assertEquals(saved,m.get("checkout:"+A));assertEquals("unknown",new JSONObject(saved).getString("phase"));}
 @Test public void legacyCheckoutCannotBecomeCanonicalOrRotateOriginalUnknownRecord()throws Exception{Memory m=new Memory();cart(m);m.put("checkout:"+A,new JSONObject().put("account",A).put("key","old-original-key").put("fingerprint",new JSONObject().put("CartRevision","old").toString()).toString());String original=m.get("checkout:"+A);assertThrows(CheckoutIntent.UnresolvedException.class,()->CheckoutIntent.prepareSyncedCart(m,session("a".repeat(64)),new JSONObject(),id->"store_original"));assertEquals(original,m.get("checkout:"+A));}
 @Test public void authorizationFailurePrecedesDurableCheckoutDispatchAndCannotSend()throws Exception{Memory m=new Memory();PrivacyLifecycle lifecycle=new PrivacyLifecycle(m);PrivacyLifecycle.Ticket ticket=lifecycle.admit(A,"POST","/orders",new JSONObject().put("IdempotencyKey","original-key"));AtomicInteger dispatch=new AtomicInteger(),send=new AtomicInteger();assertThrows(IOException.class,()->ApiClient.executeTracked(lifecycle,ticket,()->true,new ApiClient.NetworkCall(){public void prepare()throws Exception{throw new IOException("authority unavailable");}public void admitDispatch(){dispatch.incrementAndGet();}public ApiClient.Response send(){send.incrementAndGet();return null;}}));assertEquals(0,dispatch.get());assertEquals(0,send.get());}
 @Test public void lostInvoiceAndLegacyPendingOnlyReadOriginalReferenceWithoutChangingKeys()throws Exception{Memory m=new Memory();ProductSession s=session("a".repeat(64));BuyerPaymentReview.Pending first=BuyerPaymentReview.prepare(m,s,order());assertTrue(first.mayCreate());BuyerPaymentReview.markDispatched(m,s,first);BuyerPaymentReview.Pending cold=BuyerPaymentReview.restore(m,session("b".repeat(64)));assertFalse(cold.mayCreate());assertEquals(first.original.key,cold.original.key);assertThrows(SecurityException.class,()->BuyerPaymentReview.markDispatched(m,s,cold));Memory old=new Memory();PayHandoffRecovery.Prepared saved=PayHandoffRecovery.prepare(old,s,order());BuyerPaymentReview.Pending migration=BuyerPaymentReview.prepare(old,s,order());assertFalse(migration.mayCreate());assertEquals(saved.key,migration.original.key);}
 @Test public void receiptLaunchAndColdReadbackKeepOriginalInvoiceAndNeverClaimPaid()throws Exception{Memory m=new Memory();ProductSession s=session("a".repeat(64));BuyerPaymentReview.Pending first=BuyerPaymentReview.prepare(m,s,order());BuyerPaymentReview.markDispatched(m,s,first);String intent=m.get(first.original.namespace);assertEquals("ynxpay://invoice/inv_original",BuyerPaymentReview.received(m,s,first,invoice()));BuyerPaymentReview.opened(m,s,first);BuyerPaymentReview.Pending cold=BuyerPaymentReview.restore(m,session("b".repeat(64)));assertEquals("wallet_opened",cold.phase);BuyerPaymentReview.observed(m,s,cold,invoice().getJSONObject("order"));assertEquals(intent,m.get(first.original.namespace));assertFalse(cold.mayCreate());assertFalse(m.get(first.original.namespace+"_review_v2").contains("\"paid\""));assertThrows(SecurityException.class,()->BuyerPaymentReview.observed(m,s,cold,invoice().getJSONObject("order").put("InvoiceID","inv_other")));}
 @Test public void alreadyBoundOriginalInvoiceCanOnlyBeRead()throws Exception{Memory m=new Memory();ProductSession s=session("a".repeat(64));BuyerPaymentReview.Pending pending=BuyerPaymentReview.prepare(m,s,invoice().getJSONObject("order"));assertFalse(pending.mayCreate());assertThrows(SecurityException.class,()->BuyerPaymentReview.markDispatched(m,s,pending));assertEquals("ynxpay://invoice/inv_original",BuyerPaymentReview.received(m,s,pending,invoice()));assertFalse(BuyerPaymentReview.restore(m,s).mayCreate());}
 @Test public void mismatchedReceiptAndFailedStoragePreserveOriginalRecovery()throws Exception{Memory m=new Memory();ProductSession s=session("a".repeat(64));BuyerPaymentReview.Pending first=BuyerPaymentReview.prepare(m,s,order());String old=m.get(first.original.namespace+"_review_v2");assertThrows(Exception.class,()->BuyerPaymentReview.received(m,s,first,invoice().put("intentId","other")));assertEquals(old,m.get(first.original.namespace+"_review_v2"));m.fail=true;assertThrows(IOException.class,()->BuyerPaymentReview.markDispatched(m,s,first));assertEquals(old,m.get(first.original.namespace+"_review_v2"));}
 @Test public void callbackIsOnlyFixedWakeHintAndCannotSupplyAccountOrderPaidOrExecution()throws Exception{assertTrue(BuyerPaymentReview.callbackHint("ynxshop://orders"));for(String uri:new String[]{"ynxshop://orders?paid=true","ynxshop://orders/other","ynxshop://orders#paid","ynxshop://orders?account="+B,"ynxshop://other","https://foreign.invalid/orders"})assertFalse(BuyerPaymentReview.callbackHint(uri));}
 @Test public void paidPresentationRequiresCompleteMatchingBackendSettlement()throws Exception{ProductSession s=session("a".repeat(64));JSONObject order=order().put("Status","paid").put("InvoiceID","inv_original").put("PayIntentID","intent_original").put("PayMerchant","merchant").put("PayPayoutAddress",B);assertThrows(Exception.class,()->BuyerOrderReadback.validate(order,s));JSONObject receipt=new JSONObject().put("Status","paid").put("InvoiceID","inv_original").put("IntentID","intent_original").put("Merchant","merchant").put("PayoutAddress",B).put("Payer",A).put("Currency","YNXT").put("AmountYNXT",8).put("BlockHeight",12).put("TransactionHash","0x"+"a".repeat(64));order.put("Settlement",receipt);BuyerOrderReadback.validate(order,s);receipt.put("AmountYNXT",9);assertThrows(SecurityException.class,()->BuyerOrderReadback.validate(order,s));}
 @Test public void nativePoliciesMatchOriginalGoRoutesAndRetireMissingSettlementAlias()throws Exception{assertEquals(NativeProductState.canonical(NativeProductState.buyerScopes()),NativeProductState.canonical(NativeBusinessPolicy.scopes("GET","/api/orders")));assertEquals(NativeProductState.canonical(NativeProductState.buyerScopes()),NativeProductState.canonical(NativeBusinessPolicy.scopes("POST","/api/orders/ord_original/transition")));assertEquals("[\"account:read\",\"shop:orders:write\"]",NativeProductState.canonical(NativeBusinessPolicy.scopes("GET","/api/orders/ord_original/pay-handoff")));assertEquals("[\"account:read\",\"shop:orders:write\"]",NativeProductState.canonical(NativeBusinessPolicy.scopes("POST","/api/orders/ord_original/confirm-payment")));assertThrows(SecurityException.class,()->NativeBusinessPolicy.scopes("GET","/api/orders/ord_original/settlement"));}
 @Test public void originalQueuedNativeCheckoutOnlyUsesExplicitOriginalTargetReadback()throws Exception{
  Memory m=new Memory();cart(m);ProductSession current=session("a".repeat(64));CheckoutIntent.Prepared checkout=CheckoutIntent.prepareSyncedCart(m,current,new JSONObject().put("Line1","original"),id->"store_original");CheckoutIntent.markDispatched(m,current,checkout.body);
  JSONObject item=new JSONObject().put("id","old-original-queue-id").put("account",A).put("privacyGeneration",0).put("method","POST").put("path","/orders").put("body",checkout.body);m.put("offline_mutations",new JSONArray().put(item).toString());AtomicInteger reads=new AtomicInteger();
  int count=new OfflineMutationQueue(m).flush(new OfflineMutationQueue.Sender(){public ProductSession session(){return current;}public JSONObject requestForSession(String method,String path,JSONObject body,ProductSession expected,long generation)throws Exception{assertEquals("POST",method);assertEquals("/orders/intent-lookup",path);assertEquals(1,body.length());assertEquals(checkout.body.getString("IdempotencyKey"),body.getString("IdempotencyKey"));reads.incrementAndGet();return order().put("CartConsumption",new JSONObject().put("PreviousRevision","original-cart-revision").put("Revision","consumed-revision"));}},current,0);
  assertEquals(1,count);assertEquals(1,reads.get());assertEquals("",m.get("checkout:"+A));assertEquals(0,new JSONArray(m.get("offline_mutations")).length());
 }
 @Test public void unknownCheckoutColdCartMutationsPreserveOriginalBytesAndSendNothing()throws Exception{
  for(boolean legacy:new boolean[]{false,true}){
   Memory m=new Memory();cart(m);ProductSession current=session("a".repeat(64));CheckoutIntent.Prepared checkout=CheckoutIntent.prepareSyncedCart(m,current,new JSONObject().put("Line1","original"),id->"store_original");CheckoutIntent.markDispatched(m,current,checkout.body);
   if(legacy){JSONObject saved=new JSONObject(m.get("checkout:"+A));saved.remove("phase");m.put("checkout:"+A,saved.toString());}
   Map<String,String> original=new HashMap<>(m.data);AtomicInteger sends=new AtomicInteger();
   NativeCart.Sender sender=new NativeCart.Sender(){public ProductSession session(){return current;}public JSONObject request(String method,String path,JSONObject body,ProductSession expected,long generation)throws Exception{sends.incrementAndGet();return new JSONObject().put("WalletBuyer",A).put("Buyer",A).put("Revision","new-remote").put("Items",new JSONArray());}};
   assertThrows(CheckoutIntent.UnresolvedException.class,()->NativeCart.edit(m,A,new JSONArray()));assertEquals(original,m.data);
   assertThrows(CheckoutIntent.UnresolvedException.class,()->NativeCart.refresh(m,sender,current,0));assertEquals(original,m.data);
   assertThrows(CheckoutIntent.UnresolvedException.class,()->NativeCart.sync(m,sender,current,0));assertEquals(original,m.data);
   NativeCart.Conflict conflict=new NativeCart.Conflict(new JSONObject().put("Buyer",A).put("Revision","another-device").put("Items",new JSONArray()),"original-stamp");
   assertThrows(CheckoutIntent.UnresolvedException.class,()->NativeCart.resolve(m,sender,current,0,conflict,true));assertEquals(original,m.data);assertEquals(0,sends.get());
   JSONObject receipt=order().put("CartConsumption",new JSONObject().put("PreviousRevision","original-cart-revision").put("Revision","consumed"));assertTrue(CheckoutIntent.confirmedReceipt(m,A,checkout.body,receipt));NativeCart.edit(m,A,new JSONArray());assertEquals("",m.get("checkout:"+A));
  }
 }

 @Test public void checkoutDispatchDuringRemoteCartReadCannotOverwritePurchasedDraft()throws Exception{
  Memory m=new Memory();cart(m);ProductSession current=session("a".repeat(64));CheckoutIntent.Prepared checkout=CheckoutIntent.prepareSyncedCart(m,current,new JSONObject().put("Line1","original"),id->"store_original");
  String cart=m.get("cart:"+A),metadata=m.get(NativeCart.key(A));
  NativeCart.Sender sender=new NativeCart.Sender(){public ProductSession session(){return current;}public JSONObject request(String method,String path,JSONObject body,ProductSession expected,long generation)throws Exception{CheckoutIntent.markDispatched(m,current,checkout.body);return new JSONObject().put("Buyer",A).put("Revision","remote-after-consumption").put("Items",new JSONArray());}};
  assertThrows(CheckoutIntent.UnresolvedException.class,()->NativeCart.refresh(m,sender,current,0));assertEquals(cart,m.get("cart:"+A));assertEquals(metadata,m.get(NativeCart.key(A)));assertEquals("unknown",new JSONObject(m.get("checkout:"+A)).getString("phase"));assertEquals(checkout.body.getString("IdempotencyKey"),new JSONObject(m.get("checkout:"+A)).getString("key"));
 }

}
